  <!-- the eight wires -->
  <g stroke="var(--line)">
    <path d="M30 52 H 366"/><path d="M30 70 H 366"/><path d="M30 88 H 366"/><path d="M30 106 H 366"/>
    <path d="M30 124 H 366"/><path d="M30 142 H 366"/><path d="M30 160 H 366"/><path d="M30 178 H 366"/>
  </g>
